import { sourceSpan } from './source';
import type { Candidate, Diagnostic, GlyphKind, Policy, RecognitionContext, Recognizer, SourceDocument } from './types';

export const DEFAULT_GLYPHS: Readonly<Record<string, GlyphKind>> = Object.freeze(Object.fromEntries(
  Object.entries({ horizontal: '-─━═╌╍┄┅┈┉–—_', vertical: '|│┃┆┊║¦╎╏:',
    joint: "+\\`'├└┝┞┟┠┡┢┣┗┖╠╚╟╙╰╘╞┌╭┐┘┬┴┼", left: '<←', right: '>→›',
    up: '^↑', down: 'v↓' }).flatMap(([kind, chars]) => [...chars].map(ch => [ch, kind as GlyphKind]))));

const branch: Recognizer = {
  id: 'branch-marker', starts: ['joint', 'vertical', 'horizontal', 'right', '↳', '↪', '➜', '➝', '➞'],
  recognize({ row, column, glyphs, policy }) {
    const start = column - 1;
    if (policy.compatibility) {
      const marker = policy.compatibility === 'ascii-tree-1'
        ? /^([+`\\]--(?:>)?)(?=\s+\S)/ : /^([+`\\|]--(?:>)?)(?=\s+\S)/;
      const match = marker.exec(row.text.slice(start));
      return match ? [{ kind: 'branch', endColumn: column + match[0].length, headed: match[0].endsWith('>') }] : [];
    }
    let x = start;
    if (glyphs[row.text[x]] === 'joint' || glyphs[row.text[x]] === 'vertical') x++;
    const dashStart = x;
    while (glyphs[row.text[x]] === 'horizontal') x++;
    const dashes = x - dashStart;
    if (glyphs[row.text[x]] === 'right') x++;
    const standalone = /[├└┣┗╠╚╰→↳↪➜➝➞]/.test(row.text[start]) && row.text[start + 1] === ' ';
    if (standalone && x <= start + 1) x = start + 1;
    else if (!dashes || (dashStart === start && dashes < 2 && x === start + dashes)) return [];
    if (x === start || x >= row.text.length || glyphs[row.text[x]] === 'joint') return [];
    return [{ kind: 'branch', endColumn: x + 1, headed: glyphs[row.text[x - 1]] === 'right' }];
  }
};
const bullet: Recognizer = {
  id: 'list-marker', starts: ['-', '+', '*', '•', '●', '◦', '▪', '▸', '▹', 'digit'],
  recognize({ row, column, policy }) {
    if (policy.compatibility || policy.dialect === 'graph') return [];
    if (!/^[ |│┃║:]*$/.test(row.text.slice(0, column - 1))) return [];
    const match = /^(?:[-+*•●◦▪▸▹]|\d+[.)])(?= +\S)/.exec(row.text.slice(column - 1));
    return match ? [{ kind: 'branch', endColumn: column + match[0].length, bullet: true }] : [];
  }
};
const route: Recognizer = {
  id: 'reference-run', starts: ['horizontal', 'joint', 'left'],
  recognize({ row, column, glyphs }) {
    const start = column - 1;
    let x = start;
    if (glyphs[row.text[x]] === 'left' || glyphs[row.text[x]] === 'joint') x++;
    const dashStart = x;
    while (x < row.text.length) {
      if (glyphs[row.text[x]] === 'horizontal') x++;
      else if ((glyphs[row.text[x]] === 'joint' || glyphs[row.text[x]] === 'vertical') && glyphs[row.text[x + 1]] === 'horizontal') x++;
      else break;
    }
    if (x === dashStart) return [];
    if (['joint', 'right'].includes(glyphs[row.text[x]])) x++;
    const last = glyphs[row.text[x - 1]];
    if (glyphs[row.text[start]] !== 'left' && last !== 'joint' && last !== 'right') return [];
    return [{ kind: 'route', endColumn: x + 1, headed: last === 'right' || glyphs[row.text[start]] === 'left' }];
  }
};
const vertical: Recognizer = {
  id: 'vertical-stroke', starts: ['vertical', 'up', 'down'],
  recognize({ row, column, glyphs }) {
    const ch = row.text[column - 1];
    if (glyphs[ch] === 'vertical' && ch !== ':') return [{ kind: 'vertical', endColumn: column + 1 }];
    if (['up', 'down'].includes(glyphs[ch]) && (column === row.text.length || row.text[column] === ' ') &&
      (column === 1 || row.text[column - 2] === ' ')) return [{ kind: 'vertical', endColumn: column + 1 }];
    return [];
  }
};
export const DEFAULT_RECOGNIZERS: readonly Recognizer[] = Object.freeze([branch, bullet, route, vertical]);

export function recognize(source: SourceDocument, policy: Policy, glyphs: Readonly<Record<string, GlyphKind>>,
  additions: readonly Recognizer[], diagnostics: Diagnostic[]): Candidate[] {
  const rules = [...DEFAULT_RECOGNIZERS, ...additions];
  if (new Set(rules.map(rule => rule.id)).size !== rules.length) throw new Error('Recognizer IDs must be unique');
  const dispatch = new Map<string, Recognizer[]>();
  for (const rule of rules) for (const feature of new Set(rule.starts)) {
    dispatch.set(feature, [...(dispatch.get(feature) ?? []), rule]);
  }
  const result: Candidate[] = [];
  for (const row of source.rows) {
    if (row.kind !== 'content') continue;
    const closing: string[] = [];
    for (let x = 0; x < row.text.length; x++) {
      const ch = row.text[x];
      if (ch in { '[': 1, '{': 1, '(': 1 }) closing.push(({ '[': ']', '{': '}', '(': ')' } as Record<string, string>)[ch]);
      else if (closing.length && ch === closing.at(-1)) { closing.pop(); continue; }
      if (closing.length) continue;
      // Start a horizontal/jointed run once, while retaining branch/route overlap.
      if (x && glyphs[row.text[x - 1]] === 'horizontal' && ['horizontal', 'joint', 'right'].includes(glyphs[ch])) continue;
      const features = [ch, glyphs[ch], /\d/.test(ch) ? 'digit' : ''];
      const applicable = new Set(features.flatMap(feature => dispatch.get(feature) ?? []));
      const context: RecognitionContext = Object.freeze({ source, row, column: x + 1, glyphs, policy });
      for (const rule of [...applicable].sort((a, b) => a.id.localeCompare(b.id))) {
        for (const proposal of rule.recognize(context)) {
          if (!['branch', 'route', 'vertical'].includes(proposal.kind) || !Number.isInteger(proposal.endColumn) ||
            proposal.endColumn <= x + 1 || proposal.endColumn > row.text.length + 1) throw new Error(`Invalid candidate from ${rule.id}`);
          const span = sourceSpan(row, x + 1, proposal.endColumn);
          const id = `${rule.id}:${row.line}:${x + 1}:${proposal.endColumn}:${proposal.kind}`;
          if (result.length >= policy.maxCandidates) throw new RangeError('Diagram exceeds maxCandidates');
          const { endColumn: _, ...details } = proposal;
          result.push({ ...details, id, ruleId: rule.id, span });
        }
      }
    }
    if (closing.length) diagnostics.push({ code: 'unclosed-label-delimiter', line: row.line,
      severity: 'warning', message: 'An unclosed label delimiter protects the remaining text from connector recognition.' });
  }
  return result.sort((a, b) => a.span.line - b.span.line || a.span.column - b.span.column || a.id.localeCompare(b.id));
}

import type { DiagramInterpretation, Diagnostic, SourceSpan } from './types';

export interface RenderedDiagram {
  text: string;
  /** One source range per output UTF-16 unit; inserted newlines have no range. */
  sourceMap: (Pick<SourceSpan, 'start' | 'end'> | null)[];
  diagnostics: Diagnostic[];
}

/** Optional normalized preview. Placements are transactional; collisions never overwrite text. */
export function renderCleaned(result: DiagramInterpretation): RenderedDiagram {
  type Cell = { ch: string; start: number; end: number };
  const original: Cell[][] = result.source.rows.map(row => [...Array(row.text.length)].map((_, x) => ({
    ch: row.text[x], start: row.offsets[x][0], end: row.offsets[x][1] })));
  const canvas = original.map(row => row.map(cell => ({ ...cell })));
  const placements: { line: number; column: number; cell: Cell }[] = [];
  const blank = (line: number, column: number) => { if (canvas[line - 1][column - 1]) canvas[line - 1][column - 1].ch = ' '; };
  for (const repair of result.repairs) for (const move of repair.moves) {
    const row = original[move.line - 1];
    if (repair.kind === 'tree-alignment') {
      const node = result.nodes.find(n => n.spans[0].line === move.line && n.branchColumn === move.column);
      if (!node) continue;
      for (let x = move.column; x < node.spans[0].endColumn; x++) {
        blank(move.line, x);
        placements.push({ line: move.line, column: x + move.toColumn - move.column, cell: row[x - 1] });
      }
    } else {
      const cell = row[move.column - 1];
      blank(move.line, move.column);
      placements.push({ line: move.line, column: move.toColumn, cell });
      const kind = (ch: string | undefined) => result.glyphs[ch ?? ''];
      const crossing = kind(cell.ch) === 'vertical' && kind(row[move.column - 2]?.ch) === 'horizontal' && kind(row[move.column]?.ch) === 'horizontal';
      if (kind(cell.ch) === 'joint' || crossing) {
        for (let x = move.column; x < move.toColumn; x++) {
          placements.push({ line: move.line, column: x, cell: { ...cell, ch: '-' } });
        }
        // A crossing slides along its horizontal channel.
        if (kind(canvas[move.line - 1][move.toColumn - 1]?.ch) === 'horizontal') blank(move.line, move.toColumn);
      }
    }
  }
  const serialize = (rows: Cell[][], diagnostics: Diagnostic[]): RenderedDiagram => {
    let text = '';
    const sourceMap: RenderedDiagram['sourceMap'] = [];
    rows.forEach((row, index) => {
      if (index) { text += '\n'; sourceMap.push(null); }
      for (const cell of row) { text += cell.ch; sourceMap.push({ start: cell.start, end: cell.end }); }
    });
    return { text, sourceMap, diagnostics };
  };
  for (const { line, column, cell } of placements) {
    const row = canvas[line - 1];
    while (row.length < column) row.push({ ch: ' ', start: cell.start, end: cell.start });
    if (row[column - 1].ch !== ' ' && row[column - 1].ch !== cell.ch && cell.ch !== ' ') {
      return serialize(original, [{ code: 'render-collision', severity: 'error', line,
        message: 'Repair placements overlap; the preview retains the normalized original.' }]);
    }
    if (cell.ch !== ' ') row[column - 1] = { ...cell };
  }
  return serialize(canvas, []);
}

import type { Diagnostic, Policy, SourceDocument, SourceRow, SourceSpan } from './types';

const ANSI = /^(?:\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\))/;
const INVISIBLE = /[\ufeff\u200b\u200c\u200d]/;
const SPACE = /[\u00a0\u202f\u2007]/;
const ALLOWED_FENCES = new Set(['', 'ascii', 'text', 'txt', 'tree', 'plaintext', 'console']);

export function sourceSpan(row: SourceRow, column: number, endColumn: number): SourceSpan {
  const first = row.offsets[column - 1];
  const last = row.offsets[endColumn - 2];
  return { line: row.line, column, endColumn,
    start: first?.[0] ?? row.start + row.raw.length,
    end: last?.[1] ?? first?.[0] ?? row.start + row.raw.length };
}

export function normalizeSource(original: string, policy: Policy, diagnostics: Diagnostic[]): SourceDocument {
  const rows: { line: number; raw: string; text: string; start: number; block: number;
    kind: SourceRow['kind']; offsets: [number, number][] }[] = [];
  const lines = original.split(/\r\n|\r|\n/);
  let offset = 0;
  for (const [index, raw] of lines.entries()) {
    let text = '';
    const offsets: [number, number][] = [];
    for (let i = 0; i < raw.length;) {
      const ansi = raw[i] === '\x1b' ? ANSI.exec(raw.slice(i)) : null;
      if (ansi) { i += ansi[0].length; continue; }
      if (INVISIBLE.test(raw[i])) { i++; continue; }
      const count = raw[i] === '\t' ? policy.tabSize - text.length % policy.tabSize : 1;
      const ch = raw[i] === '\t' || SPACE.test(raw[i]) ? ' ' : raw[i];
      if (text.length + count > policy.maxColumns) throw new RangeError('Diagram exceeds maxColumns');
      text += ch.repeat(count);
      for (let k = 0; k < count; k++) offsets.push([offset + i, offset + i + 1]);
      i++;
    }
    rows.push({ line: index + 1, raw, text, start: offset, offsets, block: 0,
      kind: text.trim() ? 'content' : 'blank' });
    offset += raw.length + (original.slice(offset + raw.length, offset + raw.length + 2) === '\r\n' ? 2 : 1);
  }
  const nonblank = rows.filter(row => row.text.trim());
  if (nonblank.length && nonblank.every(row => /^\s*> ?/.test(row.text))) {
    for (const row of rows) {
      const prefix = /^\s*> ?/.exec(row.text)?.[0].length ?? 0;
      row.text = row.text.slice(prefix);
      row.offsets = row.offsets.slice(prefix);
    }
  }
  let fence: { ch: string; length: number; allowed: boolean; line: number } | undefined;
  let block = 0;
  let hasSelectedFence = false;
  const inSelected = new Set<number>();
  for (const row of rows) {
    const match = /^\s*(`{3,}|~{3,})([^`]*)$/.exec(row.text);
    if (match && !fence) {
      fence = { ch: match[1][0], length: match[1].length,
        allowed: ALLOWED_FENCES.has(match[2].trim().toLowerCase()), line: row.line };
      hasSelectedFence ||= fence.allowed;
      row.kind = 'metadata';
      row.block = ++block;
    } else if (match && fence && match[1][0] === fence.ch && match[1].length >= fence.length && !match[2].trim()) {
      row.kind = 'metadata'; row.block = block++; fence = undefined;
    } else {
      row.block = block;
      if (fence?.allowed) inSelected.add(row.line);
      else if (fence) row.kind = 'outside';
    }
  }
  if (fence) diagnostics.push({ code: 'unclosed-fence', line: fence.line,
    severity: 'warning', message: 'The code fence is not closed.' });
  if (hasSelectedFence) for (const row of rows) {
    if (!inSelected.has(row.line) && row.kind !== 'metadata') row.kind = 'outside';
  }
  // Frames are document wrappers only when both matching horizontal edges exist.
  for (let i = 0; i < rows.length; i++) {
    const top = /^( *)([+┌┏╔╭])[-─━═]{3,}([+┐┓╗╮])\s*$/.exec(rows[i].text);
    if (!top || rows[i].kind !== 'content') continue;
    const left = top[1].length;
    const right = rows[i].text.trimEnd().length - 1;
    let bottom = i + 1;
    while (bottom < rows.length && rows[bottom].block === rows[i].block &&
      /^[|│┃║]$/.test(rows[bottom].text[left] ?? '') && /^[|│┃║]$/.test(rows[bottom].text[right] ?? '')) bottom++;
    if (bottom === i + 1 || !/^[+└┗╚╰][-─━═]+[+┘┛╝╯]$/.test(rows[bottom]?.text.slice(left, right + 1) ?? '')) continue;
    rows[i].kind = rows[bottom].kind = 'metadata';
    for (let y = i + 1; y < bottom; y++) {
      const row = rows[y];
      row.text = row.text.slice(0, left) + ' ' + row.text.slice(left + 1, right) + ' ' + row.text.slice(right + 1);
    }
    i = bottom;
  }
  return Object.freeze({ original, rows: Object.freeze(rows.map(row => Object.freeze({ ...row,
    offsets: Object.freeze(row.offsets.map(pair => Object.freeze(pair))) }))) });
}

