import { mutableFixture } from '../../../../tests/support/mappingDiagram';
import { expect, it } from 'vitest';
import { buildDiagramContent, type DiagramContent } from '../../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../../core/diagrams/diagramContentNodes';
import { RevisionedDiagramService } from '../../../core/diagrams/diagramService';
import { patchDiagram } from '../../../core/diagrams/patchDiagram';
import { singleDiagramScene } from '../../../core/diagrams/projectDiagramCanvas';
import { mappingDocumentFromScene } from '../../workspace/mappingDocument';
import { initialCanvasState } from '../../workspace/mappingWorkspace';
import { diffDiagramContent, type DiagramDiffSide } from '../diagramContentDiff';
import { diffChangeDocument } from '../changeDocumentDiff';
import { controllerBefore, controllerPatch, expectedAddedLabels, expectedUnchangedLabels } from './controllerDiffFixture';
import { floatingBefore, floatingAfter } from './floatingPaneDiffFixture';

const tree = (ascii: string, revision = 'new:1') => buildDiagramContent(ascii, revision, 'tree');
const node = (content: DiagramContent, label: string) => diagramContentNodes(content).find(n => n.label === label)!;
const decoration = (side: DiagramDiffSide, content: DiagramContent, label: string) => side.nodes.get(node(content, label).id);

it('recovers the renamed DisplayNodeBase inside an inserted FloatingPane', () => {
  const before = tree(floatingBefore, 'before'), after = tree(floatingAfter, 'after');
  const diff = diffDiagramContent(before, after);
  expect(diff.counts).toEqual({ added: 2, removed: 0, modified: 1, moved: 2 });
  expect(decoration(diff.proposed, after, 'DisplayNodeBase')).toEqual({ status: 'modified', moved: true, containsChanges: true });
  for (const label of ['expandedGeometry?', 'geometryPolicy', 'placement: automatic | manual', 'sizing: content | fixed']) {
    expect(decoration(diff.proposed, after, label), label).toBeUndefined();
  }
  expect(decoration(diff.proposed, after, 'FloatingPane')).toEqual({ status: 'added', containsChanges: true });
  expect(decoration(diff.proposed, after, 'SelectionRegion')).toEqual({ moved: true });
});

it('recovers several edited field labels without treating unrelated replacements as renames', () => {
  const before = tree('Root\n|-- placement: automatic | manual\n`-- sizing: content | fixed');
  const after = tree('Root\n|-- placement = automatic / manual\n`-- sizing = content / fixed');
  expect(diffDiagramContent(before, after).counts).toEqual({ added: 0, removed: 0, modified: 2, moved: 0 });
  expect(diffDiagramContent(tree('Root\n|-- A\n`-- B'), tree('Root\n|-- X\n`-- Y')).counts)
    .toEqual({ added: 2, removed: 2, modified: 0, moved: 0 });
});

it('highlights the expected text in the actual controller/session demo', () => {
  const before = new RevisionedDiagramService().create({ id: 'controller', revision: 0, ascii: controllerBefore, structureKind: 'tree' }).diagram;
  const patch = patchDiagram(before, 9, 23, controllerPatch);
  const after = patch.diagram.content;
  const diff = diffDiagramContent(before.content, after, Object.fromEntries([...patch.nodeIds].map(([a, b]) => [b, a])));
  for (const label of expectedAddedLabels) expect(decoration(diff.proposed, after, label)?.status, label).toBe('added');
  for (const label of expectedUnchangedLabels) expect(decoration(diff.proposed, after, label), label).toBeUndefined();
  expect(decoration(diff.proposed, after, 'AgentDiagrammingSessionService')).toEqual({ containsChanges: true });
  expect(decoration(diff.original, before.content, 'CanvasSessionBridge -> browser poll/reply')?.status).toBe('removed');
  expect([...diff.proposed.lines.keys()].map(line => after.ascii.split('\n')[line - 1])).toEqual([
    'Original / Proposed switches the preview snapshot.', 'Session edits persist without saving originals.', 'Acceptance into originals is a future step.'
  ]);
});

it('matches across revision IDs and colors only changed labels, with ancestor indicators', () => {
  const a = tree('Root\n|-- Original\n`-- Keep', 'old:0'), b = tree('Root\n|-- Proposed\n`-- Keep');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 0, removed: 0, modified: 1, moved: 0 });
  expect(decoration(diff.proposed, b, 'Proposed')).toEqual({ status: 'modified' });
  expect(decoration(diff.original, a, 'Original')).toEqual({ status: 'modified' });
  expect(decoration(diff.proposed, b, 'Root')).toEqual({ containsChanges: true });
  expect(decoration(diff.proposed, b, 'Keep')).toBeUndefined();
});

it('insertion shifts source lines without marking unchanged siblings as moved', () => {
  const a = tree('Root\n|-- A\n`-- B'), b = tree('Root\n|-- New\n|-- A\n`-- B');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 1, removed: 0, modified: 0, moved: 0 });
  expect(decoration(diff.proposed, b, 'New')).toEqual({ status: 'added' });
  expect(decoration(diff.proposed, b, 'B')).toBeUndefined();
});

it('deletions appear on Original and mark the surviving parent on both versions', () => {
  const a = tree('Root\n|-- Branch\n|   `-- Gone\n`-- Keep'), b = tree('Root\n|-- Branch\n`-- Keep');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts.removed).toBe(1);
  expect(decoration(diff.original, a, 'Gone')).toEqual({ status: 'removed' });
  expect(decoration(diff.proposed, b, 'Branch')).toEqual({ containsChanges: true });
});

it('identifies a moved subtree without marking its descendants as moved', () => {
  const a = tree('Root\n|-- A\n|   `-- Moving\n|       `-- Leaf\n`-- B');
  const b = tree('Root\n|-- A\n`-- B\n    `-- Moving\n        `-- Leaf');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 0, removed: 0, modified: 0, moved: 1 });
  expect(decoration(diff.proposed, b, 'Moving')).toEqual({ moved: true });
  expect(decoration(diff.proposed, b, 'Leaf')).toBeUndefined();
  expect(decoration(diff.proposed, b, 'A')?.containsChanges).toBe(true);
  expect(decoration(diff.proposed, b, 'B')?.containsChanges).toBe(true);
});

it('distinguishes sibling reordering from mere line shifts', () => {
  const a = tree('Root\n|-- A\n|-- B\n`-- C'), b = tree('Root\n|-- C\n|-- A\n`-- B');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts.moved).toBe(1);
  expect(decoration(diff.proposed, b, 'C')?.moved).toBe(true);
});

it('does not invent matches when repeated labels lose an indistinguishable sibling', () => {
  const a = tree('Root\n|-- Same\n|-- Same\n`-- Keep'), b = tree('Root\n|-- Same\n`-- Keep');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 1, removed: 2, modified: 0, moved: 0 });
});

it('preserves equal repeated siblings when another label changes', () => {
  const a = tree('Root\n|-- Same\n|-- Same\n`-- Old'), b = tree('Root\n|-- Same\n|-- Same\n`-- New');
  expect(diffDiagramContent(a, b).counts).toEqual({ added: 0, removed: 0, modified: 1, moved: 0 });
});

it('uses exact patch provenance to disambiguate surviving repeated nodes', () => {
  const original = new RevisionedDiagramService().create({ id: 'd', revision: 0, ascii: 'Root\n|-- Same\n|-- Same\n`-- Keep', structureKind: 'tree' }).diagram;
  const patched = patchDiagram(original, 2, 2, '');
  const origins = Object.fromEntries([...patched.nodeIds].map(([old, next]) => [next, old]));
  const diff = diffDiagramContent(original.content, patched.diagram.content, origins);
  expect(diff.counts).toEqual({ added: 0, removed: 1, modified: 0, moved: 0 });
});

it('compares cumulative edits against baseline and clears highlights on revert', () => {
  const original = new RevisionedDiagramService().create({ id: 'd', revision: 0, ascii: 'Root\n|-- A\n`-- B', structureKind: 'tree' }).diagram;
  const one = patchDiagram(original, 2, 2, '|-- X').diagram;
  const two = patchDiagram(one, 3, 3, '`-- Y').diagram;
  expect(diffDiagramContent(original.content, two.content).counts.modified).toBe(0); // multi-label gap is ambiguous
  expect(diffDiagramContent(original.content, two.content).counts.added).toBe(2);
  const partial = patchDiagram(two, 2, 2, '|-- A').diagram;
  expect(diffDiagramContent(original.content, partial.content).counts.modified).toBe(1);
  const reverted = patchDiagram(partial, 3, 3, '`-- B').diagram;
  expect(diffDiagramContent(original.content, reverted.content).proposed.nodes.size).toBe(0);
});

it('compares unparsed notes without leaking highlighting into another diagram', () => {
  // Legacy trees can have prose outside their structural node index.
  const prose = (ascii: string): DiagramContent => ({ ...tree(ascii), structure: { kind: 'tree', parserVersion: 'ascii-tree-1', rootIds: [], nodes: {} } });
  const a = prose('Unchanged note\nOld note\nFinal note'), b = prose('Unchanged note\nNew note\nFinal note');
  const diff = diffDiagramContent(a, b);
  expect([...diff.original.lines]).toEqual([[2, 'modified']]);
  expect([...diff.proposed.lines]).toEqual([[2, 'modified']]);
  const scene = singleDiagramScene(a.ascii);
  scene.contents = { overview: new RevisionedDiagramService().create({ id: 'overview', revision: 0, ascii: a.ascii }).diagram };
  scene.contents = { ...scene.contents, overview: { ...scene.contents.overview, content: a } };
  const baseline = { document: mappingDocumentFromScene(scene), canvas: initialCanvasState() };
  const proposed = structuredClone(baseline); proposed.document.scene.contents = { ...proposed.document.scene.contents, overview: { ...proposed.document.scene.contents.overview, content: b } };
  if (proposed.document.scene.root.kind !== 'container') throw Error();
  proposed.document.scene.root.children = [...proposed.document.scene.root.children,
    { id: 'added', kind: 'diagram', contentId: 'added', collapsed: false, position: { column: 40, row: 0 } }];
  proposed.document.scene.contents = { ...proposed.document.scene.contents,
    added: new RevisionedDiagramService().create({ id: 'added', revision: 0, ascii: 'Added\n`-- Child', structureKind: 'tree' }).diagram };
  const doc = { id: 'doc', name: 'Canvas', baseline, proposed, version: 1, past: [], future: [] };
  const both = diffChangeDocument(doc);
  expect(both.diagrams.get('grid:overview')?.proposed.lines.get(2)).toBe('modified');
  expect(both.diagrams.get('grid:added')?.counts.added).toBe(2);
  expect(both.counts).toEqual({ added: 2, removed: 0, modified: 1, moved: 0 });
});

it('marks every node in a new or removed diagram and supports a renamed parent with unchanged children', () => {
  const a = tree('Old parent\n`-- Child'), b = tree('New parent\n`-- Child');
  expect(diffDiagramContent(undefined, b).counts.added).toBe(2);
  expect(diffDiagramContent(a, undefined).counts.removed).toBe(2);
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 0, removed: 0, modified: 1, moved: 0 });
});

it('shows independent modifications on two diagrams in the same canvas', () => {
  const scene = singleDiagramScene('First\n`-- Before');
  scene.contents = { overview: new RevisionedDiagramService().create({ id: 'overview', revision: 0, ascii: 'First\n`-- Before', structureKind: 'tree' }).diagram,
    second: new RevisionedDiagramService().create({ id: 'second', revision: 0, ascii: 'Second\n`-- Before', structureKind: 'tree' }).diagram };
  if (scene.root.kind !== 'container') throw Error();
  scene.root.children = [...scene.root.children, { id: 'second', kind: 'diagram', contentId: 'second', position: { column: 30, row: 0 }, collapsed: false }];
  const baseline = { document: mappingDocumentFromScene(scene), canvas: initialCanvasState() }, proposed = structuredClone(baseline);
  proposed.document.scene.contents = Object.fromEntries(Object.entries(scene.contents).map(([id, d]) => [id, patchDiagram(d, 2, 2, '`-- After').diagram]));
  const result = diffChangeDocument({ id: 'doc', name: 'Canvas', baseline, proposed, version: 1, past: [], future: [] });
  expect(result.counts.modified).toBe(2);
  expect(result.diagrams.get('grid:overview')?.counts.modified).toBe(1);
  expect(result.diagrams.get('grid:second')?.counts.modified).toBe(1);
});

it('flags folded unparsed notes and moving a node out of a removed parent', () => {
  const a = mutableFixture(tree('Root\n`-- Child\nOld note', 'old')), b = mutableFixture(tree('Root\n`-- Child\nNew note'));
  // Model a parser that leaves the final line as prose in Root's fold range.
  for (const c of [a, b]) if (c.structure.kind === 'tree') {
    c.structure.nodes = Object.fromEntries(Object.entries(c.structure.nodes).filter(([, n]) => n.line < 3));
    c.structure.nodes[node(c, 'Root').id].foldRanges = [{ startLine: 2, endLine: 3 }];
  }
  const result = diffDiagramContent(a, b);
  expect(result.proposed.lines.get(3)).toBe('modified');
  expect(decoration(result.proposed, b, 'Root')?.containsChanges).toBe(true);
  const moved = diffDiagramContent(tree('Removed parent\n`-- Surviving\n    `-- Grandchild'), tree('Surviving\n`-- Grandchild'));
  expect(moved.counts).toEqual({ added: 0, removed: 1, modified: 0, moved: 1 });
});

import { expect, it } from 'vitest';
import { buildDiagramContent, type DiagramContent } from '../../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../../core/diagrams/diagramContentNodes';
import { RevisionedDiagramService } from '../../../core/diagrams/diagramService';
import { patchDiagram } from '../../../core/diagrams/patchDiagram';
import { diffDiagramContent } from '../diagramContentDiff';

const tree = (text: string, revision = 'new', version: 'ascii-tree-1' | 'ascii-tree-2' = 'ascii-tree-2') => buildDiagramContent(text, revision, 'tree', version);
const node = (content: DiagramContent, label: string) => diagramContentNodes(content).find(node => node.label === label)!;
const topology = (content: DiagramContent) => {
  const nodes = diagramContentNodes(content), byId = new Map(nodes.map(node => [node.id, node]));
  return nodes.map(node => [node.label, byId.get(node.parentId ?? '')?.label]);
};

it('handles nested partial wrappers and their removal without moving deeper descendants', () => {
  const a = tree('Root\n|-- A\n|   `-- Leaf\n`-- Keep', 'old');
  const b = tree('Root\n|-- Outer\n|   `-- Inner\n|       `-- A\n|           `-- Leaf\n`-- Keep');
  expect(diffDiagramContent(a, b).counts).toEqual({ added: 2, removed: 0, modified: 0, moved: 1 });
  expect(diffDiagramContent(b, a).counts).toEqual({ added: 0, removed: 2, modified: 0, moved: 1 });
  expect(diffDiagramContent(a, b).proposed.nodes.get(node(b, 'Leaf').id)).toBeUndefined();
});

it('recovers a moved and renamed container, then an edited child in its new context', () => {
  const a = tree('Root\n|-- A\n|   `-- Before\n|       |-- Anchor\n|       `-- Old field\n`-- B', 'old');
  const b = tree('Root\n|-- A\n`-- B\n    `-- After\n        |-- Anchor\n        `-- New field');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 0, removed: 0, modified: 2, moved: 1 });
  expect(diff.proposed.nodes.get(node(b, 'After').id)).toEqual({ status: 'modified', moved: true, containsChanges: true });
  expect(diff.proposed.nodes.get(node(b, 'Anchor').id)).toBeUndefined();
});

it('detects reordering with an unrelated insertion', () => {
  const a = tree('Root\n|-- A\n|-- B\n`-- C', 'old'), b = tree('Root\n|-- New\n|-- C\n|-- A\n`-- B');
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 1, removed: 0, modified: 0, moved: 1 });
  expect(diff.proposed.nodes.get(node(b, 'C').id)).toEqual({ moved: true });
});

it('compares forests without leaking parents across blank lines', () => {
  const a = tree('First\n`-- Moving\n\nSecond\n`-- Keep', 'old');
  const b = tree('First\n`-- Added\n\nSecond\n|-- Keep\n`-- Moving');
  expect(topology(a)).toEqual([['First', undefined], ['Moving', 'First'], ['Second', undefined], ['Keep', 'Second']]);
  expect(topology(b)).toEqual([['First', undefined], ['Added', 'First'], ['Second', undefined], ['Keep', 'Second'], ['Moving', 'Second']]);
  expect(diffDiagramContent(a, b).counts).toEqual({ added: 1, removed: 0, modified: 0, moved: 1 });
});

it.each(['+--', '`--', '\\--', '|--'])('preserves v2 topology across the %s branch marker', marker => {
  const a = tree('Root\n`-- Leaf', 'old'), b = tree(`Root\n${marker} Leaf`);
  expect(topology(b)).toEqual([['Root', undefined], ['Leaf', 'Root']]);
  expect(diffDiagramContent(a, b).counts).toEqual({ added: 0, removed: 0, modified: 0, moved: 0 });
});

it('retains legacy grammar and does not turn parser metadata changes into a visual diff', () => {
  const ascii = 'Root\n|-- A\n`-- B', a = tree(ascii, 'old', 'ascii-tree-1'), b = tree(ascii);
  expect(topology(a)).toEqual([['B', undefined]]);
  expect(topology(b)).toEqual([['Root', undefined], ['A', 'Root'], ['B', 'Root']]);
  const snapshot = structuredClone(a);
  expect(diffDiagramContent(a, b).counts).toEqual({ added: 0, removed: 0, modified: 0, moved: 0 });
  expect(a).toEqual(snapshot);
  expect(diffDiagramContent(tree('Root\n+-- Old\n`-- Keep', 'old', 'ascii-tree-1'),
    tree('Root\n+-- New\n`-- Keep', 'new', 'ascii-tree-1')).counts.modified).toBe(1);
});

it('retains headed-branch and indentation-only parsing contracts', () => {
  const headed = tree('Root\n+--> Leaf');
  expect(topology(headed)).toEqual([['Leaf', undefined]]);
  const a = tree('Root\n  Old child', 'old'), b = tree('Root\n  New child');
  expect(topology(a)).toEqual([]);
  expect([...diffDiagramContent(a, b).proposed.lines]).toEqual([[2, 'modified']]);
});

it('ignores branch spacing and connector-only lines without fabricating moves', () => {
  const a = tree('Root\n|-- A\n`-- B', 'old'), b = tree('\nRoot\n|\n|--   A\n|\n`-- B\n');
  expect(topology(b)).toEqual(topology(a));
  expect(diffDiagramContent(a, b).counts).toEqual({ added: 0, removed: 0, modified: 0, moved: 0 });
});

it('keeps internal tree-label spacing as text but ignores trimmed trailing whitespace', () => {
  const a = tree('Root\n|-- placement automatic\n`-- Keep', 'old');
  expect(diffDiagramContent(a, tree('Root\n|-- placement    automatic\n`-- Keep')).counts.modified).toBe(1);
  expect(diffDiagramContent(a, tree('Root\n|-- placement automatic   \n`-- Keep ')).counts.modified).toBe(0);
});

it('addresses independent mixed-mode columns and repeated occurrences on the same row', () => {
  const a = buildDiagramContent('Left    Right\n|-- Same    |-- Same\n`-- EndL    `-- EndR', 'old');
  const b = buildDiagramContent('Left    Right\n|-- Same    |-- Edit\n`-- EndL    `-- EndR', 'new');
  const repeated = diagramContentNodes(a).filter(node => node.label === 'Same');
  expect(repeated).toHaveLength(2);
  expect(repeated[0].line).toBe(repeated[1].line);
  expect(repeated[0].startColumn).not.toBe(repeated[1].startColumn);
  const diff = diffDiagramContent(a, b);
  expect(diff.counts).toEqual({ added: 0, removed: 0, modified: 1, moved: 0 });
  expect(diff.original.nodes.get(repeated[0].id)).toBeUndefined();
  expect(diff.original.nodes.get(repeated[1].id)?.status).toBe('modified');
  const edited = node(b, 'Edit');
  expect(b.ascii.split('\n')[edited.line - 1].slice(edited.startColumn - 1, edited.endColumn)).toBe('Edit');
});

it('keeps unmarked continuation text separate and visible in the raw-line diff', () => {
  const a = tree('Root\n|-- Ready /\n|   Applied\n`-- End', 'old');
  const b = tree('Root\n|-- Ready /\n|   Pending\n`-- End');
  expect(topology(a)).toEqual([['Root', undefined], ['Ready /', 'Root'], ['End', 'Root']]);
  const diff = diffDiagramContent(a, b);
  expect([...diff.proposed.lines]).toEqual([[3, 'modified']]);
  expect(diff.proposed.nodes.get(node(b, 'Root').id)).toEqual({ containsChanges: true });
});

it('falls back to raw lines for multiline mixed-mode prose and normalized quote coordinates', () => {
  const a = buildDiagramContent('First note\nSecond note', 'old'), b = buildDiagramContent('First note\nChanged note', 'new');
  expect([...diffDiagramContent(a, b).proposed.lines]).toEqual([[2, 'modified']]);
  const quotedA = tree('> Root\n> `-- Old', 'old'), quotedB = tree('> Root\n> `-- New');
  const diff = diffDiagramContent(quotedA, quotedB);
  expect(diff.proposed.nodes.size).toBe(0);
  expect([...diff.proposed.lines]).toEqual([[2, 'modified']]);
});

it.each(['call(a -> b) | literal ---', '[source -> target]', '{a | b}', '(unfinished -> text'])('preserves literal tree label %s', label => {
  const a = tree(`Root\n|-- ${label}\n\x60-- Old`, 'old'), b = tree(`Root\n|-- ${label}\n\x60-- New`);
  expect(node(a, label)?.label).toBe(label);
  expect(diffDiagramContent(a, b).proposed.nodes.get(node(b, label).id)).toBeUndefined();
});

it('keeps one-character and last-character label edits inside inclusive source bounds', () => {
  const a = tree('Root\n|-- X\n`-- field ending a', 'old'), b = tree('Root\n|-- Y\n`-- field ending b');
  // Both edits need enough evidence: the long field anchors recovery of the single-character gap.
  expect(diffDiagramContent(a, b).counts.modified).toBe(2);
  const character = node(b, 'Y');
  expect(character.startColumn).toBe(character.endColumn);
  expect(b.ascii.split('\n')[character.line - 1].slice(character.startColumn - 1, character.endColumn)).toBe('Y');
});

it('does not mutate content/provenance after a broad patch or depend on patch history for unique nodes', () => {
  const a = new RevisionedDiagramService().create({ id: 'test', revision: 0, ascii: 'Root\n|-- Before\n|   `-- Leaf\n`-- Keep', structureKind: 'tree' }).diagram;
  const text = 'Root\n|-- Wrapper\n|   `-- After\n|       `-- Leaf\n`-- Keep';
  const patched = patchDiagram(a, 1, 4, text);
  const origins = Object.fromEntries([...patched.nodeIds].map(([old, next]) => [next, old]));
  const snapshot = structuredClone({ a, diagram: patched.diagram, origins });
  const diff = diffDiagramContent(a.content, patched.diagram.content, origins);
  expect(diff.counts).toEqual({ added: 1, removed: 0, modified: 1, moved: 1 });
  expect(diffDiagramContent(a.content, tree(text, 'independent-history')).counts).toEqual(diff.counts);
  expect({ a, diagram: patched.diagram, origins }).toEqual(snapshot);
  const reverted = patchDiagram(patched.diagram, 1, 5, a.content.ascii);
  expect(diffDiagramContent(a.content, reverted.diagram.content).counts).toEqual({ added: 0, removed: 0, modified: 0, moved: 0 });
});

it.each(['', '   ', 'Root\tChild', 'Root\r\nChild', 'Root\n\u2514-- Child', '\x1b[31mRed', 'x'.repeat(20001)])('preserves strict builder input validation (%#)', ascii => {
  expect(() => tree(ascii)).toThrow('printable ASCII');
});

it('normalizes patch newlines while retaining trailing blank lines and rejecting invalid ranges', () => {
  const original = new RevisionedDiagramService().create({ id: 'd', revision: 0, ascii: 'Root\n`-- Old', structureKind: 'tree' }).diagram;
  const next = patchDiagram(original, 2, 2, '|-- New\r\n`-- Added\r').diagram.content;
  expect(next.ascii).toBe('Root\n|-- New\n`-- Added\n');
  expect(() => patchDiagram(original, 0, 1, 'X')).toThrow();
  expect(() => patchDiagram(original, 1, 3, 'X')).toThrow();
  expect(() => patchDiagram(original, 1, 2, '')).toThrow();
});

import { describe, expect, it } from 'vitest';
import { buildDiagramContent, type DiagramContentNode } from '../../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../../core/diagrams/diagramContentNodes';
import { matchDiagramNodes, MAX_LABEL_ALIGNMENT_NODES } from '../diagramNodeMatcher';
import { diffDiagramContent } from '../diagramContentDiff';

type Tree = { label: string; children: Tree[] };
const t = (label: string, ...children: Tree[]): Tree => ({ label, children });
function content(root: Tree, revision = 'old') {
  const lines = [root.label];
  const expected: { label: string; parent?: string }[] = [{ label: root.label }];
  const visit = (node: Tree, prefix: string) => node.children.forEach((child, i) => {
    const last = i === node.children.length - 1;
    lines.push(prefix + (last ? '`-- ' : '|-- ') + child.label);
    expected.push({ label: child.label, parent: node.label });
    visit(child, prefix + (last ? '    ' : '|   '));
  });
  visit(root, '');
  const result = buildDiagramContent(lines.join('\n'), revision, 'tree');
  const nodes = diagramContentNodes(result), byId = new Map(nodes.map(node => [node.id, node]));
  // Do not accidentally test a topology that the application's parser doesn't produce.
  expect(nodes.map(node => ({ label: node.label, parent: node.parentId ? byId.get(node.parentId)!.label : undefined }))).toEqual(expected);
  return result;
}
const nodes = (root: Tree, revision: string) => diagramContentNodes(content(root, revision));
const byLabel = (values: readonly DiagramContentNode[], label: string) => values.find(node => node.label === label)!;
function matches(old: Tree, next: Tree) {
  const a = nodes(old, 'old'), b = nodes(next, 'new');
  const result = matchDiagramNodes(a, b);
  return { ...result, a, b, peer: (label: string) => b.find(node => node.id === result.forward.get(byLabel(a, label).id))?.label };
}

describe('exact anchors and conservative identity', () => {
  it('preserves the exact Root when a wrapper has the same descendants', () => {
    const result = matches(t('Root', t('Leaf')), t('Wrapper', t('Root', t('Leaf'))));
    expect(result.peer('Root')).toBe('Root');
    expect(result.forward.size).toBe(2);
  });

  it('preserves containers A/B rather than renaming them to explain a move', () => {
    const result = matches(t('Root', t('A', t('Moving', t('Leaf'))), t('B')),
      t('Root', t('A'), t('B', t('Moving', t('Leaf')))));
    expect(result.a.map(node => result.peer(node.label))).toEqual(result.a.map(node => node.label));
  });

  it('matches an entire exact subtree including repeated descendants', () => {
    const result = matches(t('Root', t('Group', t('Same'), t('Same')), t('Other')),
      t('Root', t('Other'), t('Wrapper', t('Group', t('Same'), t('Same')))));
    expect(result.forward.size).toBe(5);
    const oldSame = result.a.filter(node => node.label === 'Same'), newSame = result.b.filter(node => node.label === 'Same');
    expect(oldSame.map(node => result.forward.get(node.id))).toEqual(newSame.map(node => node.id));
  });

  it('does not partially map an exact subtree that conflicts with provenance', () => {
    const a = nodes(t('Root', t('Group', t('Same'), t('Same')), t('Keep')), 'old');
    const b = nodes(t('Root', t('Group', t('Same'), t('Same')), t('Added'), t('Keep')), 'new');
    const oldSame = a.filter(node => node.label === 'Same'), newSame = b.filter(node => node.label === 'Same');
    const result = matchDiagramNodes(a, b, { [newSame[1].id]: oldSame[0].id });
    expect(result.forward.get(oldSame[0].id)).toBe(newSame[1].id);
    expect(result.forward.has(oldSame[1].id)).toBe(false);
    expect(result.reverse.get(newSame[1].id)).toBe(oldSame[0].id);
  });

  it('leaves indistinguishable deletion unresolved, but accepts exact surviving provenance', () => {
    const a = nodes(t('Root', t('Same'), t('Same'), t('Keep')), 'old');
    const b = nodes(t('Root', t('Same'), t('Keep')), 'new');
    const same = a.filter(node => node.label === 'Same'), survivor = byLabel(b, 'Same');
    expect(matchDiagramNodes(a, b).reverse.has(survivor.id)).toBe(false);
    const result = matchDiagramNodes(a, b, { [survivor.id]: same[1].id });
    expect(result.reverse.get(survivor.id)).toBe(same[1].id);
    expect(result.forward.has(same[0].id)).toBe(false);
  });

  it('preserves a copied subtree in its established parent context', () => {
    const result = matches(t('Root', t('A', t('Copy', t('Leaf'))), t('B')),
      t('Root', t('A', t('Copy', t('Leaf'))), t('B', t('Copy', t('Leaf')))));
    const copy = result.b.find(node => node.id === result.forward.get(byLabel(result.a, 'Copy').id))!;
    expect(result.b.find(node => node.id === copy.parentId)?.label).toBe('A');
    expect(result.forward.size).toBe(result.a.length);
  });

  it('disambiguates repeated labels by distinct descendants after reordering', () => {
    const result = matches(t('Root', t('Same', t('Alpha')), t('Same', t('Beta'))),
      t('Root', t('Same', t('Beta')), t('Same', t('Alpha'))));
    for (const old of result.a.filter(node => node.label === 'Same')) {
      const next = result.b.find(node => node.id === result.forward.get(old.id))!;
      expect(result.forward.get(old.childIds[0])).toBe(next.childIds[0]);
    }
  });

  it('ignores stale, mismatched and conflicting hints without breaking bijection', () => {
    const a = nodes(t('Root', t('Same'), t('Same'), t('Keep')), 'old');
    const b = nodes(t('Root', t('Same'), t('Same'), t('Keep'), t('New')), 'new');
    const same = a.filter(node => node.label === 'Same'), peers = b.filter(node => node.label === 'Same');
    const hints = { stale: same[0].id, [peers[0].id]: same[0].id, [peers[1].id]: same[0].id,
      [byLabel(b, 'Keep').id]: 'missing', [byLabel(b, 'New').id]: byLabel(a, 'Root').id };
    const result = matchDiagramNodes(a, b, hints);
    expect(result.forward.get(same[0].id)).toBe(peers[0].id);
    expect(result.forward.get(same[1].id)).toBe(peers[1].id);
    expect(result.reverse.has(byLabel(b, 'New').id)).toBe(false);
    expect(new Set(result.forward.values()).size).toBe(result.forward.size);
  });
});

describe('renamed containers and edited siblings', () => {
  it('finds a renamed child rather than the new competing wrapper', () => {
    const result = matches(t('Root', t('Original parent', t('Leaf'))),
      t('Root', t('Wrapper', t('Renamed parent', t('Leaf')))));
    expect(result.peer('Original parent')).toBe('Renamed parent');
    expect(result.reverse.has(byLabel(result.b, 'Wrapper').id)).toBe(false);
  });

  it('recovers nested renamed parents from the bottom up', () => {
    const result = matches(t('Root', t('Outer old', t('Inner old', t('Leaf')))),
      t('Root', t('Wrapper', t('Outer new', t('Inner new', t('Leaf'))))));
    expect(result.peer('Outer old')).toBe('Outer new');
    expect(result.peer('Inner old')).toBe('Inner new');
  });

  it('keeps equally supported split containers unresolved', () => {
    const result = matches(t('Root', t('Original', t('One'), t('Two')), t('Keep')),
      t('Root', t('First', t('One')), t('Second', t('Two')), t('Keep')));
    expect(result.peer('Original')).toBeUndefined();
    expect(result.peer('One')).toBe('One');
    expect(result.peer('Two')).toBe('Two');
  });

  it('keeps equally supported merge containers unresolved in either direction', () => {
    const a = t('Root', t('First', t('One')), t('Second', t('Two')), t('Keep'));
    const b = t('Root', t('Merged', t('One'), t('Two')), t('Keep'));
    expect(matches(a, b).peer('First')).toBeUndefined();
    expect(matches(a, b).peer('Second')).toBeUndefined();
    expect(matches(b, a).peer('Merged')).toBeUndefined();
  });

  it('uses parent context for repeated leaves without stealing the other branch', () => {
    const result = matches(t('Root', t('A', t('Same')), t('B', t('Same'))),
      t('Root', t('A', t('Edited')), t('B', t('Same'))));
    const old = result.a.filter(node => node.label === 'Same');
    expect(result.forward.get(old[0].id)).toBe(byLabel(result.b, 'Edited').id);
    expect(result.forward.get(old[1].id)).toBe(byLabel(result.b, 'Same').id);
  });

  it('aligns distinct edited fields around an inserted sibling', () => {
    const result = matches(t('Root', t('placement: automatic | manual'), t('sizing: content | fixed')),
      t('Root', t('placement = automatic / manual'), t('Description'), t('sizing = content / fixed')));
    expect(result.peer('placement: automatic | manual')).toBe('placement = automatic / manual');
    expect(result.peer('sizing: content | fixed')).toBe('sizing = content / fixed');
    expect(result.reverse.has(byLabel(result.b, 'Description').id)).toBe(false);
  });

  it('does not align tied, generic fields just because their order agrees', () => {
    const result = matches(t('Root', t('field old a'), t('field old b')),
      t('Root', t('field new c'), t('field new d')));
    expect(result.forward.size).toBe(1);
  });

  it('does not require a node to stay a leaf or a container', () => {
    const a = content(t('Root', t('Branch'), t('Keep'))), b = content(t('Root', t('Branch', t('New')), t('Keep')), 'new');
    expect(diffDiagramContent(a, b).counts).toEqual({ added: 1, removed: 0, modified: 0, moved: 0 });
    expect(diffDiagramContent(b, a).counts).toEqual({ added: 0, removed: 1, modified: 0, moved: 0 });
  });

  it.each(['FIELD Name', 'field  name', 'field: name'])('retains raw changes after normalizing %s for correspondence', label => {
    const a = content(t('Root', t('field name'), t('sizing content fixed')));
    const b = content(t('Root', t(label), t('sizing: content | fixed')), 'new');
    expect(diffDiagramContent(a, b).counts.modified).toBe(2);
  });
});

describe('invariants and bounded recovery', () => {
  it.each([63, 64, 65])('bounds label alignment at %i unmatched nodes while preserving anchors', size => {
    // Distinct long alphabetic keys provide a clear textual winner for every field.
    const key = (i: number) => String.fromCharCode(97 + Math.floor(i / 26)).repeat(6) + String.fromCharCode(97 + i % 26).repeat(6);
    const a = content(t('Root', ...Array.from({ length: size }, (_, i) => t(`${key(i)}: value`)), t('Keep')));
    const b = content(t('Root', ...Array.from({ length: size }, (_, i) => t(`${key(i)} = value`)), t('Keep')), 'new');
    const diff = diffDiagramContent(a, b);
    expect(diff.counts).toEqual(size <= MAX_LABEL_ALIGNMENT_NODES
      ? { added: 0, removed: 0, modified: size, moved: 0 }
      : { added: size, removed: size, modified: 0, moved: 0 });
  });

  it('keeps labels resembling object properties ordinary', () => {
    const result = matches(t('Root', t('__proto__'), t('constructor'), t('prototype')),
      t('Root', t('Added'), t('__proto__'), t('constructor'), t('prototype')));
    expect(result.forward.size).toBe(4);
  });

  it('is independent of storage order and does not mutate nodes or provenance', () => {
    const a = nodes(t('Root', t('Branch old', t('Leaf')), t('Same'), t('Same')), 'old');
    const b = nodes(t('Root', t('Wrapper', t('Branch new', t('Leaf'))), t('Same'), t('Same')), 'new');
    const before = structuredClone({ a, b });
    const origins = Object.freeze({ [byLabel(b, 'Leaf').id]: byLabel(a, 'Leaf').id });
    const freeze = (value: unknown) => {
      if (value && typeof value === 'object') { Object.values(value).forEach(freeze); Object.freeze(value); }
    };
    freeze(a); freeze(b);
    const first = matchDiagramNodes(a, b, origins), second = matchDiagramNodes([...a].reverse(), [...b].reverse(), origins);
    expect([...second.forward].sort()).toEqual([...first.forward].sort());
    expect({ a, b }).toEqual(before);
    for (const [old, next] of first.forward) expect(first.reverse.get(next)).toBe(old);
    expect(Object.keys(origins)).toHaveLength(1);
  });

  it('recovers generated unambiguous wrapper/move/rename combinations across revision IDs', () => {
    let state = 17;
    const random = () => ((state = (state * 1664525 + 1013904223) >>> 0) / 2 ** 32);
    for (let trial = 0; trial < 40; trial++) {
      const width = 2 + Math.floor(random() * 5), moving = Math.floor(random() * width);
      const branches = Array.from({ length: width }, (_, i) => t(`Branch ${i}`, t(`Leaf ${i}`)));
      const old = t('Root', t('A', ...branches), t('B'));
      const moved = t(`Branch ${moving} renamed`, t(`Leaf ${moving}`));
      const next = t('Root', t('A', ...branches.filter((_, i) => i !== moving)), t('B', t('Wrapper', moved)));
      const a = content(old, `old-${trial}`), b = content(next, `new-${trial}`);
      const oldNodes = diagramContentNodes(a), nextNodes = diagramContentNodes(b), result = matchDiagramNodes(oldNodes, nextNodes);
      expect(result.forward.size).toBe(oldNodes.length);
      expect(new Set(result.forward.values()).size).toBe(result.forward.size);
      for (const node of oldNodes) {
        const peer = nextNodes.find(nextNode => nextNode.id === result.forward.get(node.id))!;
        expect(peer.label).toBe(node.label === `Branch ${moving}` ? moved.label : node.label);
        expect(result.reverse.get(peer.id)).toBe(node.id);
        expect(b.ascii.split('\n')[peer.line - 1].slice(peer.startColumn - 1, peer.endColumn)).toBe(peer.label);
      }
      expect(diffDiagramContent(a, b).counts).toEqual({ added: 1, removed: 0, modified: 1, moved: 1 });
      expect(diffDiagramContent(b, a).counts).toEqual({ added: 0, removed: 1, modified: 1, moved: 1 });
    }
  });
});

