import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { expect, it } from 'vitest';
import { MappingWorkspaceStore } from '../mappingWorkspaceStore';
it('atomically saves validated project-scoped workspaces without disturbing the last good snapshot', async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'workspace-test-'));
  try {
    const store = new MappingWorkspaceStore(dir);
    expect(await store.load('project')).toBeNull();
    const snapshot = { schemaVersion: 3 as const, projectId: 'project', documents: [] };
    await store.save('project', snapshot); expect(await store.load('project')).toEqual(snapshot);
    await expect(store.save('other', snapshot)).rejects.toThrow('another project');
    await expect(store.save('project', { ...snapshot, schemaVersion: 99 })).rejects.toThrow('version');
    expect(await store.load('project')).toEqual(snapshot);
  } finally { await rm(dir, { recursive: true, force: true }); }
});

import { afterEach, expect, it, vi } from 'vitest';
import { mkdtemp, rm, rename, readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { WorkspaceRecordStore } from '../workspaceRecordStore';
import { initialCanvasState } from '../../../../../domain/mapping/workspace/mappingWorkspace';
import { singleDiagramScene } from '../../../../../domain/core/diagrams/projectDiagramCanvas';
import { documentPrefix, type WorkspaceBatch, type WorkspaceIndex } from '../../../../../domain/mapping/workspace/workspaceRecords';
import { MappingDocumentController } from '../../../../../domain/mapping/workspace/mappingDocumentController';
vi.mock('node:fs/promises', async importOriginal => { const actual = await importOriginal<typeof import('node:fs/promises')>(); return { ...actual, rename: vi.fn(actual.rename) }; });
const roots: string[] = [];
afterEach(async () => { vi.mocked(rename).mockClear(); await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true }))); });
async function fixture() {
  const root = await mkdtemp(path.join(tmpdir(), 'workspace-records-')); roots.push(root);
  const store = new WorkspaceRecordStore(root), document = { scene: singleDiagramScene('Alpha'), edges: [], sections: {} };
  const state = await store.state('project', async () => ({ schemaVersion: 3, projectId: 'project', activeDocumentId: 'draft-a', documents: [
    { representationId: 'draft-a', name: 'Alpha', savedName: '', savedScene: JSON.stringify(document.scene), revisionId: '', document, canvas: initialCanvasState() }
  ] }));
  const prefix = documentPrefix('draft-a');
  const batch: WorkspaceBatch = { requestId: 'rename', expectedRevision: 0, changes: [{ key: prefix + 'metadata', value: { ...state.records[prefix + 'metadata'] as object, name: 'Renamed' } }] };
  return { root, store, state, batch, prefix };
}
it('migrates once and persists a changed record without rewriting existing histories', async () => {
  const { root, store, state, batch } = await fixture(); vi.mocked(rename).mockClear();
  await store.apply('project', batch);
  expect(vi.mocked(rename).mock.calls).toHaveLength(2); // one record, one manifest
  const loaded = await new WorkspaceRecordStore(root).load('project');
  expect(loaded?.documents[0].name).toBe('Renamed');
  expect(Object.keys((await store.state('project', async () => null)).records)).toEqual(Object.keys(state.records));
});
it('recognizes identical retries after restart and rejects changed IDs and stale clients', async () => {
  const { root, store, batch } = await fixture(); await store.apply('project', batch);
  const restarted = new WorkspaceRecordStore(root);
  expect(await restarted.apply('project', batch)).toEqual({ revision: 1 });
  await expect(restarted.apply('project', { ...batch, changes: [] })).rejects.toThrow('REQUEST_ID_CONFLICT');
  await expect(restarted.apply('project', { ...batch, requestId: 'other-client' })).rejects.toThrow('VERSION_CONFLICT');
});
it('a failed manifest publication exposes the old complete workspace and can be retried', async () => {
  const { root, store, batch } = await fixture();
  const real = await vi.importActual<typeof import('node:fs/promises')>('node:fs/promises');
  vi.mocked(rename).mockImplementationOnce(real.rename).mockRejectedValueOnce(Error('disk full'));
  await expect(store.apply('project', batch)).rejects.toThrow('disk full');
  expect((await new WorkspaceRecordStore(root).load('project'))?.documents[0].name).toBe('Alpha');
  expect(await store.apply('project', batch)).toEqual({ revision: 1 });
});
it('rejects incomplete atomic removals and broken history references without replacing the manifest', async () => {
  const { store, batch, prefix } = await fixture();
  await expect(store.apply('project', { ...batch, changes: [{ key: prefix + 'history', delete: true }] })).rejects.toThrow('Incomplete');
  expect((await store.load('project'))?.documents[0].name).toBe('Alpha');
});
it('removes a canvas and its records atomically', async () => {
  const { root, store, state } = await fixture();
  const index = state.records.workspace as WorkspaceIndex;
  await store.apply('project', { requestId: 'delete', expectedRevision: 0, changes: [
    ...Object.keys(state.records).filter(key => key !== 'workspace').map(key => ({ key, delete: true as const })),
    { key: 'workspace', value: { ...index, activeDocumentId: undefined, documentIds: [] } }
  ] });
  expect((await new WorkspaceRecordStore(root).load('project'))?.documents).toEqual([]);
});
it('can reopen an initialized project before its first canvas is saved', async () => {
  const root = await mkdtemp(path.join(tmpdir(), 'empty-workspace-')); roots.push(root);
  await new WorkspaceRecordStore(root).state('project', async () => null);
  expect(await new WorkspaceRecordStore(root).state('project', async () => { throw Error('Must not migrate again'); }))
    .toEqual({ revision: 0, records: {} });
});
it('rejects deletion of a revision still referenced by an accepted checkpoint', async () => {
  const { store, state, batch } = await fixture();
  const key = Object.keys(state.records).find(key => key.includes('/revision/'))!;
  await expect(store.apply('project', { ...batch, changes: [{ key, delete: true }] })).rejects.toThrow('Invalid diagram binding');
  expect((await store.load('project'))?.documents[0].name).toBe('Alpha');
});
it('requires canvas removal to delete all its indexed records in the same batch', async () => {
  const { store, state, batch } = await fixture();
  await expect(store.apply('project', { ...batch, changes: [{ key: 'workspace', value: {
    ...state.records.workspace as WorkspaceIndex, documentIds: [], activeDocumentId: undefined
  } }] })).rejects.toThrow('Record belongs to a removed canvas');
});

it('defers historical checkpoint validation on startup without weakening full reads or new writes', async () => {
  const { root, store, prefix } = await fixture();
  const document = { scene: singleDiagramScene('Start'), edges: [], sections: {} };
  const controller = new MappingDocumentController(document, initialCanvasState());
  controller.applyUpdate(0, [{ method: 'replace', nodeId: 'grid:overview', ascii: 'Current' }]);
  const history = controller.exportHistory();
  await store.replace('project', { schemaVersion: 3, projectId: 'project', activeDocumentId: 'draft-a', documents: [{
    representationId: 'draft-a', name: 'Current', savedName: 'Current', savedScene: JSON.stringify(controller.getSnapshot().document.scene),
    revisionId: '', document: controller.getSnapshot().document, canvas: initialCanvasState(), history
  }] });
  const file = path.join(root, 'workspace-records.json');
  const manifest = JSON.parse(await readFile(file, 'utf8'));
  const key = prefix + 'checkpoint/' + history.past.at(-1);
  const checkpoint = JSON.parse(await readFile(path.join(root, 'workspace-records', manifest.records[key] + '.json'), 'utf8'));
  checkpoint.document.scene.root.kind = 'invalid';
  const text = JSON.stringify(checkpoint), hash = createHash('sha256').update(text).digest('hex');
  await writeFile(path.join(root, 'workspace-records', hash + '.json'), text);
  manifest.records[key] = hash; await writeFile(file, JSON.stringify(manifest));
  const restarted = new WorkspaceRecordStore(root);
  const state = await restarted.state('project', async () => null, 'current');
  expect(state.records[key]).toEqual(checkpoint);
  await expect(restarted.state('project', async () => null)).rejects.toThrow('Invalid canvas box kind');
  await expect(restarted.apply('project', { requestId: 'invalid-checkpoint', expectedRevision: state.revision,
    changes: [{ key, value: checkpoint }] })).rejects.toThrow('Invalid canvas box kind');
  // Integrity checking is independent of the deferred semantic validation.
  await writeFile(path.join(root, 'workspace-records', hash + '.json'), '{}');
  await expect(new WorkspaceRecordStore(root).state('project', async () => null, 'current')).rejects.toThrow('integrity');
});

import { WorkspaceRecordStore } from './workspaceRecordStore';
import type { WorkspaceBatch } from '../../../../domain/mapping/workspace/workspaceRecords';
import { DiagramPersistence } from '../../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from '../../../core/persistence/diagramRevisionStore';
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { deserializeWorkspace } from '../../../../domain/mapping/workspace/mappingWorkspaceCodec';
/** Separate from representation revisions: UI changes do not create diagram revisions. */
export class MappingWorkspaceStore {
  constructor(private readonly root: string, private readonly diagramPersistence: DiagramPersistence = new DiagramPersistence(new DiagramRevisionStore(root))) { this.records = new WorkspaceRecordStore(root); }
  private readonly records: WorkspaceRecordStore;
  loadRecords(projectId: string, historyValidation: import('../../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') { return this.records.state(projectId, () => this.loadLegacy(projectId), historyValidation); }
  applyBatch(projectId: string, batch: WorkspaceBatch) { return this.records.apply(projectId, batch); }
  async load(projectId: string): Promise<MappingWorkspaceSnapshot | null> {
    return await this.records.load(projectId) ?? this.loadLegacy(projectId);
  }
  private async loadLegacy(projectId: string): Promise<MappingWorkspaceSnapshot | null> {
    let json: string;
    try { json = await readFile(path.join(this.root, 'mapping-workspace.json'), 'utf8'); }
    catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
    // A missing referenced diagram is corruption, not a missing workspace.
    const snapshot = deserializeWorkspace(await this.diagramPersistence.restore(JSON.parse(json)));
    if (snapshot.projectId !== projectId) throw new Error('Workspace belongs to another project');
    return snapshot;
  }

  async save(projectId: string, input: unknown): Promise<void> {
    const snapshot = deserializeWorkspace(input);
    if (snapshot.projectId !== projectId) throw new Error('Workspace belongs to another project');
    if (await this.records.replace(projectId, snapshot)) return;
    const json = JSON.stringify(await this.diagramPersistence.persist(snapshot));
    await mkdir(this.root, { recursive: true });
    const temp = path.join(this.root, `.mapping-workspace-${randomUUID()}.tmp`);
    try { await writeFile(temp, json, 'utf8'); await rename(temp, path.join(this.root, 'mapping-workspace.json')); }
    finally { await rm(temp, { force: true }); }
  }
}

import { createHash, randomUUID } from 'node:crypto';
import { assertDiagramStorageFormat } from '../../../core/persistence/diagramStorageFormat';
import { mkdir, readFile, rename, rm, open } from 'node:fs/promises';
import path from 'node:path';
import { ApplicationError } from '../../../../application/core/errors';
import { recordsWorkspace, validateRecordUpdate, workspaceRecords, type WorkspaceBatch, type WorkspaceRecords, type WorkspaceRecordState } from '../../../../domain/mapping/workspace/workspaceRecords';
import type { MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { HistoryValidation } from '../../../../domain/core/diagrams/canvasHistory';

interface Manifest { schemaVersion: 1; projectId: string; revision: number; records: Record<string, string>; receipts: Record<string, { hash: string; revision: number }> }
const queues = new Map<string, Promise<unknown>>();
const hash = (value: string) => createHash('sha256').update(value).digest('hex');
/** New records become reachable only through the final atomic manifest replacement. */
export class WorkspaceRecordStore {
  private cached?: { raw: string; manifest: Manifest; records: WorkspaceRecords; historyValidation: HistoryValidation };
  constructor(private readonly root: string) {}
  private get file() { return path.join(this.root, 'workspace-records.json'); }
  private serial<T>(run: () => Promise<T>): Promise<T> {
    const next = (queues.get(this.root) ?? Promise.resolve()).catch(() => {}).then(run);
    queues.set(this.root, next);
    void next.finally(() => { if (queues.get(this.root) === next) queues.delete(this.root); }).catch(() => {});
    return next;
  }
  private async read(projectId: string, historyValidation: HistoryValidation = 'all') {
    await assertDiagramStorageFormat(this.root);
    let raw: string;
    try { raw = await readFile(this.file, 'utf8'); } catch (e) { if ((e as NodeJS.ErrnoException).code === 'ENOENT') return undefined; throw e; }
    if (this.cached?.raw === raw) {
      if (this.cached.manifest.projectId !== projectId) throw Error('Workspace belongs to another project');
      if (historyValidation === 'all' && this.cached.historyValidation !== 'all') {
        if (Object.keys(this.cached.records).length) validateRecordUpdate(this.cached.records, Object.keys(this.cached.records), projectId);
        this.cached.historyValidation = 'all';
      }
      return this.cached;
    }
    const manifest = JSON.parse(raw) as Manifest;
    if (manifest.schemaVersion !== 1 || manifest.projectId !== projectId) throw Error('Workspace belongs to another project or has an invalid version');
    const records = Object.fromEntries(await Promise.all(Object.entries(manifest.records).map(async ([key, id]) => {
      if (!/^[a-f0-9]{64}$/.test(id)) throw Error('Invalid workspace record reference');
      const text = await readFile(path.join(this.root, 'workspace-records', id + '.json'), 'utf8');
      if (hash(text) !== id) throw Error('Workspace record integrity failure');
      return [key, JSON.parse(text)];
    })));
    if (Object.keys(records).length) validateRecordUpdate(records, Object.keys(records), projectId, historyValidation);
    return this.cached = { raw, manifest, records, historyValidation };
  }
  async load(projectId: string): Promise<MappingWorkspaceSnapshot | undefined> {
    const state = await this.read(projectId); return state ? recordsWorkspace(state.records)! : undefined;
  }
  async state(projectId: string, legacy: () => Promise<MappingWorkspaceSnapshot | null>, historyValidation: HistoryValidation = 'all'): Promise<WorkspaceRecordState> {
    return this.serial(async () => {
      let state = await this.read(projectId, historyValidation);
      if (!state) {
        const snapshot = await legacy();
        const records = snapshot ? workspaceRecords(snapshot) : {};
        state = await this.publish({ schemaVersion: 1, projectId, revision: 0, records: {}, receipts: {} }, records, Object.keys(records));
      }
      return { revision: state.manifest.revision, records: state.records };
    });
  }
  async replace(projectId: string, snapshot: MappingWorkspaceSnapshot): Promise<boolean> {
    return this.serial(async () => {
      const state = await this.read(projectId); if (!state) return false;
      const records = workspaceRecords(snapshot);
      await this.publish({ ...state.manifest, revision: state.manifest.revision + 1, records: {} }, records, Object.keys(records)); return true;
    });
  }
  async apply(projectId: string, input: WorkspaceBatch): Promise<{ revision: number }> {
    return this.serial(async () => {
      if (!input || typeof input.requestId !== 'string' || !/^[\w-]{1,150}$/.test(input.requestId) || !Number.isSafeInteger(input.expectedRevision)
        || !Array.isArray(input.changes) || input.changes.length > 100000) throw Error('Invalid workspace batch');
      const state = await this.read(projectId, 'current'); if (!state) throw Error('Initialize workspace storage first');
      const digest = hash(JSON.stringify(input)), receipt = Object.hasOwn(state.manifest.receipts, input.requestId) ? state.manifest.receipts[input.requestId] : undefined;
      if (receipt) {
        if (receipt.hash !== digest) throw new ApplicationError('conflict', 'REQUEST_ID_CONFLICT: different batch');
        return { revision: receipt.revision };
      }
      if (input.expectedRevision !== state.manifest.revision) throw new ApplicationError('conflict', 'VERSION_CONFLICT: workspace changed in another client; reload before saving');
      const records = { ...state.records }, keys: string[] = [], seen = new Set<string>();
      for (const change of input.changes) {
        if (!change || typeof change.key !== 'string' || change.key.length > 1000 || Object.keys(change).some(k => !['key', 'value', 'delete'].includes(k))
          || ('delete' in change ? change.delete !== true || 'value' in change : !('value' in change))) throw Error('Invalid record change');
        if (change.key !== 'workspace' && !/^document\//.test(change.key)) throw Error('Invalid workspace key');
        if (seen.has(change.key)) throw Error('Duplicate key in batch');
        seen.add(change.key); keys.push(change.key);
        if ('delete' in change) delete records[change.key]; else {
          const previous = records[change.key];
          if (previous && change.key.includes('/revision/') && JSON.stringify(previous) !== JSON.stringify(change.value)) throw Error('Immutable diagram revision changed');
          if (previous && change.key.includes('/checkpoint/')) {
            const { transactionId: _before, ...before } = previous as Record<string, unknown>;
            const { transactionId: _after, ...after } = change.value as Record<string, unknown>;
            if (JSON.stringify(before) !== JSON.stringify(after)) throw Error('Immutable canvas checkpoint changed');
          }
          records[change.key] = change.value;
        }
      }
      validateRecordUpdate(records, keys, projectId);
      const revision = state.manifest.revision + 1;
      try {
        await this.publish({ ...state.manifest, revision, records: { ...state.manifest.records },
          receipts: { ...state.manifest.receipts, [input.requestId]: { hash: digest, revision } } }, records, keys);
      } catch (error) {
        // Publication might have succeeded before a directory fsync or response
        // failed. The client must retry this ID to discover the durable receipt.
        throw new ApplicationError('storage-unavailable', error instanceof Error ? error.message : String(error));
      }
      return { revision };
    });
  }
  private async atomic(file: string, text: string) {
    await mkdir(path.dirname(file), { recursive: true });
    const temp = `${file}.${randomUUID()}.tmp`;
    try {
      const handle = await open(temp, 'wx');
      try { await handle.writeFile(text); await handle.sync(); } finally { await handle.close(); }
      await rename(temp, file);
      const dir = await open(path.dirname(file), 'r'); try { await dir.sync(); } finally { await dir.close(); }
    } finally { await rm(temp, { force: true }); }
  }
  private async publish(manifest: Manifest, records: WorkspaceRecords, keys: string[]) {
    // Serial writes bound descriptors and memory even during initial migration.
    for (const key of keys) {
      if (!Object.hasOwn(records, key)) { delete manifest.records[key]; continue; }
      const text = JSON.stringify(records[key]), id = hash(text);
      if (manifest.records[key] !== id) {
        const file = path.join(this.root, 'workspace-records', id + '.json');
        try { if (await readFile(file, 'utf8') !== text) throw Error('Workspace record integrity failure'); }
        catch (e) { if ((e as NodeJS.ErrnoException).code !== 'ENOENT') throw e; await this.atomic(file, text); }
        manifest.records[key] = id;
      }
    }
    const raw = JSON.stringify(manifest);
    await this.atomic(this.file, raw);
    return this.cached = { raw, manifest, records, historyValidation: 'current' };
  }
}

