import { describe, expect, it } from 'vitest';
import type { ProjectedFile } from '../../../../../domain/mapping/workspace/displayModel';
import { importLegacyCompactionPresentation as sourceCodeCompaction } from '../../../../../domain/mapping/workspace/importLegacyCompactionPresentation';

function file(ranges: { startLine: number; endLine: number }[][]): ProjectedFile {
  return { sourceFile: 'example.ts', sourceSha256: 'a'.repeat(64), selectedLineCount: ranges.length,
    ascii: ['example.ts', ...ranges.map((_, index) => `  +-- operation ${index}`)].join('\n'),
    rows: [{ treeLine: 1, selected: false, sourceRanges: [{ startLine: 1, endLine: 1000 }] },
      ...ranges.map((sourceRanges, index) => ({ treeLine: index + 2, selected: true, sourceRanges }))] };
}

describe('legacy source presentation import', () => {
  it('folds only mapped ranges, retaining exact node expansion targets and unmapped gaps', () => {
    const result = sourceCodeCompaction(file([[{ startLine: 10, endLine: 20 }], [{ startLine: 40, endLine: 45 }]]));
    expect(result.compactedSource.sections).toEqual([
      { kind: 'collapsed-comment', startLine: 10, endLine: 20, comment: '  +-- operation 0',
        nodes: [{ graphLine: 1, startLine: 10, endLine: 20 }] },
      { kind: 'collapsed-comment', startLine: 40, endLine: 45, comment: '  +-- operation 1',
        nodes: [{ graphLine: 1, startLine: 40, endLine: 45 }] }
    ]);
  });

  it('merges nested and overlapping folds without losing graph nodes or their precise ranges', () => {
    const result = sourceCodeCompaction(file([
      [{ startLine: 10, endLine: 30 }], [{ startLine: 15, endLine: 20 }],
      [{ startLine: 25, endLine: 40 }], [{ startLine: 41, endLine: 45 }]
    ]));
    expect(result.entries).toHaveLength(4);
    expect(result.compactedSource.sections).toEqual([
      { kind: 'collapsed-comment', startLine: 10, endLine: 40,
        comment: '  +-- operation 0\n  +-- operation 1\n  +-- operation 2', nodes: [
          { graphLine: 1, startLine: 10, endLine: 30 }, { graphLine: 2, startLine: 15, endLine: 20 },
          { graphLine: 3, startLine: 25, endLine: 40 }
        ] },
      { kind: 'collapsed-comment', startLine: 41, endLine: 45, comment: '  +-- operation 3',
        nodes: [{ graphLine: 1, startLine: 41, endLine: 45 }] }
    ]);
  });

  it('shares duplicate ranges and retains disjoint ranges for the same graph row', () => {
    const range = { startLine: 10, endLine: 20 };
    const result = sourceCodeCompaction(file([[range, range, { startLine: 50, endLine: 60 }], [range]]));
    expect(result.entries).toHaveLength(2);
    expect(result.compactedSource.sections[0]).toMatchObject({ comment: '  +-- operation 0\n  +-- operation 1',
      nodes: [{ graphLine: 1, ...range }, { graphLine: 2, ...range }] });
    expect(result.compactedSource.sections[1]).toMatchObject({ startLine: 50, endLine: 60, comment: '  +-- operation 0' });
  });
});

import { expect, it } from 'vitest';
import { addDisplayNode, displayGeometry, emptyDisplayState, type ProjectedPane } from '../../../../../domain/mapping/workspace/displayModel';
import { updateSourceCodePane } from '../sourceCodePane';
import { initialCanvasState, type MappingWorkspaceSnapshot } from '../../../../../domain/mapping/workspace/mappingWorkspace';
import { initialMappingGrid } from '../../../../../domain/mapping/workspace/mappingGrid';
import { deserializeWorkspace, serializeWorkspace } from '../../../../../domain/mapping/workspace/mappingWorkspaceCodec';

function fixture() {
  const pane: ProjectedPane = { ...displayGeometry(), id: 'source', kind: 'projection', title: 'Source', childIds: [], expansion: 'expanded',
    content: { kind: 'source-code', projectId: 'project', sourceFile: 'a.ts', files: [], showCompactions: false, rangeIndex: 0 } };
  const document = initialMappingGrid(), canvas = initialCanvasState();
  canvas.display = addDisplayNode(emptyDisplayState(), pane);
  const snapshot: MappingWorkspaceSnapshot = { schemaVersion: 3, projectId: 'project', documents: [{ representationId: 'diagram',
    name: 'Diagram', revisionId: 'revision', savedName: 'Diagram', savedScene: JSON.stringify(document.scene), document, canvas }] };
  return snapshot;
}
it('navigates repository files without a compaction parent and persists source navigation state', () => {
  const snapshot = fixture(), canvas = snapshot.documents[0].canvas;
  canvas.display = updateSourceCodePane(canvas.display, 'source', { sourceFile: 'unmapped/helper.ts', scroll: { top: 240, left: 10 } });
  expect(canvas.display.nodes.source).toMatchObject({ title: 'unmapped/helper.ts', content: { sourceFile: 'unmapped/helper.ts' } });
  expect(deserializeWorkspace(serializeWorkspace(snapshot))).toEqual(snapshot);
  expect(updateSourceCodePane(canvas.display, 'source', { sourceFile: '../outside.ts' })).toBe(canvas.display);
});
it('rejects invalid source snapshots', () => {
  for (const patch of [{ sourceFile: '../outside.ts' }, { projectId: 'other-project' }, { rangeIndex: -1 }, { showCompactions: 'yes' }, { scroll: { top: -1, left: 0 } }]) {
    const snapshot = fixture(); Object.assign((snapshot.documents[0].canvas.display.nodes.source as ProjectedPane).content, patch);
    expect(() => deserializeWorkspace(snapshot)).toThrow('Invalid workspace');
  }
});
it('imports saved compaction presentation once, preserving source folds', () => {
  const snapshot = fixture(); const node = snapshot.documents[0].canvas.display.nodes.source as ProjectedPane;
  if (node.content.kind !== 'source-code') throw Error();
  node.content.files = [{ sourceFile: 'a.ts', sourceSha256: 'a'.repeat(64), ascii: 'method', selectedLineCount: 1,
    rows: [{ treeLine: 1, selected: true, sourceRanges: [{ startLine: 4, endLine: 8 }] }] }];
  const imported = deserializeWorkspace(snapshot);
  expect((imported.documents[0].canvas.display.nodes.source as ProjectedPane).content).toMatchObject({ files: [{ ranges: [{startLine: 4, endLine: 8}], compactedSource: { sections: [{comment: 'method'}] } }] });
  expect(deserializeWorkspace(serializeWorkspace(imported))).toEqual(imported);
});

import { describe, expect, it } from 'vitest';
import { SourcePaneViewState } from '../sourcePaneViewState';
import { deserializeWorkspace, serializeWorkspace } from '../../../../../domain/mapping/workspace/mappingWorkspaceCodec';
import fixture from '../../../../../tests/fixtures/source-pane-performance/workspace.json';

const display = () => deserializeWorkspace(fixture).documents[0].canvas.display;

describe('source viewport snapshots', () => {
  it('captures and prunes the shared CodePanel viewport independently of source-file viewers', () => {
    const state = new SourcePaneViewState(), original = display();
    const node = original.nodes['source-1'];
    if (node.kind !== 'projection') throw Error();
    node.content = { kind: 'code-panel', selectionId: 'selection', panel: { mappedResourceType: 'source-range',
      diagramId: 'diagram', revisionId: 'revision', contentHash: 'hash', selectedNodeIds: [], unmappedNodeIds: [], items: [] } };
    const binding = state.bind('source', 'source-1', '@code-panel');
    binding.connect(() => ({ top: 320, left: 8 }));
    state.prune('source', original);
    expect(state.captureDisplay('source', original).nodes['source-1']).toMatchObject({ content: { scroll: { top: 320, left: 8 } } });
    delete original.nodes['source-1']; state.prune('source', original);
    expect(binding.read()).toBeUndefined();
  });

  it('samples live DOM readers at save time without changing the display model', () => {
    const state = new SourcePaneViewState(), original = display();
    let position = { top: 12, left: 3 };
    const binding = state.bind('source', 'source-1', 'src/large.ts');
    const disconnect = binding.connect(() => position);
    position = { top: 400, left: 70 }; // A scroll event need not have been delivered yet.
    const captured = state.captureDisplay('source', original);
    expect(captured.nodes['source-1']).toMatchObject({ content: { scroll: position } });
    expect(original.nodes['source-1']).toMatchObject({ content: { scroll: { top: 0, left: 0 } } });
    expect(captured.nodes['source-2']).toBe(original.nodes['source-2']);
    expect(state.captureDisplay('source', original)).toBe(captured);
    state.setCamera('source', { offset: { x: 80, y: 90 }, scale: .8 });
    expect(state.captureDisplay('source', original)).toBe(captured); // Panning must not resubmit source contents.
    disconnect();
    position = { top: 0, left: 0 };
    expect(state.bind('source', 'source-1', 'src/large.ts').read()).toEqual({ top: 400, left: 70 });
  });

  it('isolates documents and rejects writes/cleanup from a replaced viewer', () => {
    const state = new SourcePaneViewState();
    const old = state.bind('a', 'pane', 'old.ts');
    const cleanup = old.connect(() => ({ top: 999, left: 1 }));
    state.resetPane('a', 'pane');
    const fresh = state.bind('a', 'pane', 'new.ts');
    fresh.connect(() => ({ top: 12, left: 0 }));
    old.write({ top: 555, left: 0 }); cleanup();
    expect(fresh.read()).toEqual({ top: 12, left: 0 });
    expect(state.bind('b', 'pane', 'new.ts', { top: 42, left: 0 }).read()).toEqual({ top: 42, left: 0 });
  });

  it('retains the last visible offset when an inactive document has no CSS box', () => {
    const state = new SourcePaneViewState();
    let visible = true;
    const binding = state.bind('source', 'source-1', 'src/large.ts');
    const cleanup = binding.connect(() => visible ? { top: 420, left: 30 } : undefined);
    binding.write({ top: 420, left: 30 });
    visible = false;
    expect(state.captureDisplay('source', display()).nodes['source-1']).toMatchObject({ content: { scroll: { top: 420, left: 30 } } });
    cleanup();
    expect(binding.read()).toEqual({ top: 420, left: 30 });
  });

  it('preserves hidden panes, prunes deleted panes, and excludes old-file positions', () => {
    const state = new SourcePaneViewState(), original = display();
    const binding = state.bind('source', 'source-1', 'src/large.ts');
    binding.connect(() => ({ top: 222, left: 4 }))();
    original.nodes['source-1'].expansion = 'collapsed';
    state.prune('source', original);
    expect(state.captureDisplay('source', original).nodes['source-1']).toMatchObject({ content: { scroll: { top: 222, left: 4 } } });
    expect(state.bind('source', 'source-1', 'other.ts').read()).toBeUndefined();
    delete original.nodes['source-1']; state.prune('source', original);
    expect(binding.read()).toBeUndefined();
  });

  it('round trips all five pane positions through the existing workspace codec', () => {
    const workspace = deserializeWorkspace(fixture), state = new SourcePaneViewState();
    for (let id = 1; id <= 5; id++) state.bind('source', `source-${id}`, 'src/large.ts').connect(() => ({ top: id * 100, left: id * 10 }));
    workspace.documents[0].canvas.display = state.captureDisplay('source', workspace.documents[0].canvas.display);
    state.setCamera('source', { offset: { x: 80, y: 90 }, scale: .8 });
    workspace.documents[0].viewport = state.captureCamera('source');
    const restored = deserializeWorkspace(serializeWorkspace(workspace));
    expect(restored).toEqual(workspace);
    const fresh = new SourcePaneViewState();
    expect(fresh.captureDisplay('source', restored.documents[0].canvas.display)).toBe(restored.documents[0].canvas.display);
  });
});

